  _gQi.copy(q).invert();
  _gL.copy(dir).applyQuaternion(_gQi);
  out.yaw = Math.atan2(_gL.x, _gL.z) * R2D;
  out.pitch = Math.asin(gClamp(_gL.y, -1, 1)) * R2D;
