  gazeState.velPitch += (w0*w0*(gazeState.aimPitch - gazeState.curPitch) - 2*z*w0*gazeState.velPitch) * h;
  gazeState.curYaw   += gazeState.velYaw * h;
  gazeState.curPitch += gazeState.velPitch * h;
